library(readr)
library(dplyr)
library(tidyr)
library(labelled)

# file paths
input_dir <- "data/input"

# read each file
wave_one <- read_delim(file.path(input_dir, "wave_one_lsype_young_person_2020.tab"), delim = "\t", col_types = cols(.default = col_character()))
wave_four <- read_delim(file.path(input_dir, "wave_four_lsype_young_person_2020.tab"), delim = "\t", col_types = cols(.default = col_character()))
ns8_main <- read_delim(file.path(input_dir, "ns8_2015_main_interview.tab"), delim = "\t", col_types = cols(.default = col_character()))
ns8_derived <- read_delim(file.path(input_dir, "ns8_2015_derived.tab"), delim = "\t", col_types = cols(.default = col_character()))
ns9_main <- read_delim(file.path(input_dir, "ns9_2022_main_interview.tab"), delim = "\t", col_types = cols(.default = col_character()))
ns9_derived <- read_delim(file.path(input_dir, "ns9_2022_derived_variables.tab"), delim = "\t", col_types = cols(.default = col_character()))

# merge all by NSID using full_join
merged <- wave_one %>%
  full_join(wave_four, by = "NSID") %>%
  full_join(ns8_main, by = "NSID") %>%
  full_join(ns8_derived, by = "NSID") %>%
  full_join(ns9_main, by = "NSID") %>%
  full_join(ns9_derived, by = "NSID")

# convert numeric columns to numeric where needed
# helper to convert columns with known numeric codes
numeric_vars <- c(
  # from ns8_derived
  "W8DHANVQH",
  # from ns8_main: all W8VCQU* variables
  paste0("W8VCQU0", letters[0:15]),
  # from ns9_derived
  "W9DANVQH", "W9DVNVQH",
  # from ns9_main academic and vocational ticks
  paste0("W9ACQU0", LETTERS[0:19]),
  paste0("W9VCQU0", LETTERS[0:15])
)

merged <- merged %>% mutate(across(all_of(numeric_vars), as.numeric, .names = "{.col}"))

# Standard missing value mapping function
standardize_missing <- function(x) {
  # R NA -> -3 unless already negative meaning exists
  rec <- case_when(
    is.na(x) ~ -3L,
    x == -9 ~ -9L,
    x == -8 ~ -8L,
    x == -7 ~ -7L,
    x == -6 ~ -6L,
    x == -5 ~ -5L,
    x == -4 ~ -4L,
    x == -3 ~ -3L,
    x == -2 ~ -2L,
    x == -1 ~ -1L,
    TRUE ~ as.integer(x)
  )
  rec
}

# ---------------------------------
# Educ25 - collapsed NVQ scheme at age 25
# ---------------------------------
# Mapping for vocational tick boxes to NVQ tier
# 0 = NVQ 4–5, 1 = NVQ 1–3, 2 = Entry level or none, 3 = Other, 4 = None

# define mapping for each W8VCQU variable (we use vector of variable names in order)
vc_vars <- c(
  "W8VCQU0A", "W8VCQU0B", "W8VCQU0C", "W8VCQU0D", "W8VCQU0E",
  "W8VCQU0F", "W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J",
  "W8VCQU0K", "W8VCQU0L", "W8VCQU0M", "W8VCQU0N", "W8VCQU0O",
  "W8VCQU0P", "W8VCQU0Q", "W8VCQU0R"
)

# mapping function: returns NVQ tier or NA
map_vc_to_tier <- function(val) {
  # val: 1 Yes => tier, 0 No => NA
  if (is.na(val)) return(NA)
  if (val == -9) return(-9)
  if (val == -8) return(-8)
  if (val == -1) return(-1)
  if (val == 1) {
    # determine tier based on variable context (captured by outer variable name)
    # use mapping defined below
    return(NA) # placeholder, will handle outside
  }
  if (val == 0) return(NA)
  return(NA)
}

# We'll handle mapping via a named vector of tiers for Yes values
# tier mapping: 0=NVQ 4-5, 1=NVQ 1-3, 2=Entry/no, 3=Other, 4=None
# we approximate mapping based on variable name
vc_tier_map <- c(
  W8VCQU0A = 1, # Youth training certificate - NVQ1-3
  W8VCQU0B = 1, # Key Skills - NVQ1-3
  W8VCQU0C = 1, # Basic skills - NVQ1-3
  W8VCQU0D = 2, # Entry level - Entry
  W8VCQU0E = 0, # Modern apprenticeship - NVQ4-5
  W8VCQU0F = 0, # RSA/OCR - NVQ4-5
  W8VCQU0G = 0, # City & Guilds - NVQ4-5
  W8VCQU0H = 0, # GNVQ - NVQ4-5
  W8VCQU0I = 1, # NVQ Level 1-2 - NVQ1-3
  W8VCQU0J = 0, # NVQ Level 3-5 - NVQ4-5
  W8VCQU0K = 0, # HNC/HND - NVQ4-5
  W8VCQU0L = 0, # ONC/OND - NVQ4-5
  W8VCQU0M = 0, # BTEC/BEC/TEC/EdExcel/LQL - NVQ4-5
  W8VCQU0N = 0, # SCOTVEC, SCOTEC or SCOTBEC - NVQ4-5
  W8VCQU0O = 3, # Other vocational - Other
  W8VCQU0P = 3, # None of the above - Other
  W8VCQU0Q = -9, # Don't know - handled separately
  W8VCQU0R = -9  # Refused - handled separately
)

# compute highest tier from vocational ticks
educ25_vc_tier <- vector("numeric", nrow(merged))
for (i in seq_along(vc_vars)) {
  var <- vc_vars[i]
  val <- merged[[var]]
  tier <- if (var %in% names(vc_tier_map)) {
    if (is.na(val)) NA
    else if (val == 1) vc_tier_map[[var]]
    else if (val == 0) NA
    else if (val == -9) -9
    else if (val == -8) -8
    else if (val == -1) -1
    else NA
  } else NA
  # keep highest numeric tier (0 >1 >2 >3 >4?) Actually higher NVQ tier is lower numeric code? We defined 0=NVQ4-5 (higher), 1=NVQ1-3, 2=Entry, 3=Other, 4=None. So we want smallest code that is not NA and not missing.
  if (!is.na(tier) && !is.na(educ25_vc_tier[i])) {
    if (educ25_vc_tier[i] > tier) educ25_vc_tier[i] <- tier
  } else if (!is.na(tier)) {
    educ25_vc_tier[i] <- tier
  }
}

# Academic NVQ level from W8DHANVQH
# map academic NVQ to collapsed scheme
map_academic_nvq_to_collapsed <- function(val) {
  if (is.na(val)) return(NA)
  if (val == -9) return(-9)
  if (val == -8) return(-8)
  if (val == -1) return(-1)
  # val 1-5, 95,96
  if (val %in% 1:5) {
    # 1-3 -> 1, 4-5 ->0
    if (val <= 3) return(1L) else return(0L)
  }
  if (val == 0) return(2L) # entry level
  if (val == 95) return(3L) # other
  if (val == 96) return(4L) # none
  return(NA)
}

educ25_academic <- sapply(merged$W8DHANVQH, map_academic_nvq_to_collapsed)

# choose highest tier between vocational and academic (higher numeric? lower code indicates higher NVQ)
educ25_collapsed <- vector("numeric", nrow(merged))
for (i in seq_len(nrow(merged))) {
  vc_tier <- educ25_vc_tier[i]
  ac_tier <- educ25_academic[i]
  # prefer higher NVQ (lower numeric code). If both present, choose min
  tiers <- c(vc_tier, ac_tier)
  tiers <- tiers[!is.na(tiers)]
  if (length(tiers) == 0) {
    educ25_collapsed[i] <- NA
  } else {
    educ25_collapsed[i] <- min(tiers)
  }
}

# handle missing mapping: convert NA to -3 unless original had negative
# We need to keep original negative codes from sources
# For educ25, if all source vars are negative codes, keep that code
# We'll check if any source var had negative >0? complex. Simplify: if educ25_collapsed is NA, set -3
educ25_collapsed[is.na(educ25_collapsed)] <- -3

# set labels
educ25_factor <- factor(educ25_collapsed, levels = 0:4, labels = c("NVQ 4–5 equivalent","NVQ 1–3 equivalent","Entry level or no qualifications","Other qualifications not mappable to the NVQ framework","None of these qualifications"), ordered = TRUE)

# ---------------------------------
# Educ32 collapsed NVQ scheme
# ---------------------------------
# map academic NVQ
educ32_academic <- sapply(merged$W9DANVQH, map_academic_nvq_to_collapsed)
# map vocational NVQ
educ32_voc <- sapply(merged$W9DVNVQH, map_academic_nvq_to_collapsed)
# combine choosing higher NVQ (lower numeric code), preserving missing codes
educ32_collapsed <- vector("numeric", nrow(merged))
for (i in seq_len(nrow(merged))) {
  ac <- educ32_academic[i]
  vc <- educ32_voc[i]
  # if either is negative code like -9, -8 etc, keep that code
  if (!is.na(ac) && ac < 0) {
    educ32_collapsed[i] <- ac
  } else if (!is.na(vc) && vc < 0) {
    educ32_collapsed[i] <- vc
  } else {
    tiers <- c(ac, vc)
    tiers <- tiers[!is.na(tiers)]
    if (length(tiers) == 0) educ32_collapsed[i] <- NA else educ32_collapsed[i] <- min(tiers)
  }
}
educ32_collapsed[is.na(educ32_collapsed)] <- -3
educ32_factor <- factor(educ32_collapsed, levels = 0:4, labels = c("NVQ 4–5 equivalent","NVQ 1–3 equivalent","Entry level or no qualifications","Other qualifications not mappable to the NVQ framework","None of these qualifications"), ordered = TRUE)

# ---------------------------------
# Educadtl32 - detailed academic qualifications
# ---------------------------------
# list of academic tick boxes in order
acad_vars <- paste0("W9ACQU0", LETTERS[0:19])
# function to compute code
compute_acad_code <- function(row) {
  code <- NULL
  last_substantive <- 0
  for (i in seq_along(acad_vars)) {
    val <- row[[acad_vars[i]]]
    if (is.na(val)) next
    if (val == -3) next # Not asked -> treat as missing, continue
    if (val == -1) next # Not applicable
    if (val == -8) { code <- -8; return(code) }
    if (val == -9) { code <- -9; return(code) }
    if (val == -2) { code <- -2; return(code) }
    if (val == 1 || val == 2) {
      last_substantive <- last_substantive + 1
      # if Yes (1)
      if (val == 1) { code <- last_substantive; return(code) }
      # if No (2) continue to next
    }
  }
  # if we finished loop without returning
  if (last_substantive == 0) {
    return(-3)
  } else {
    # all substantive were No
    return(last_substantive + 1)
  }
}

educadtl32_code <- apply(merged, 1, compute_acad_code)
# Convert to factor with labels
# get labels for each substantive var
acad_labels <- sapply(acad_vars, function(v) {
  sub <- sub("Academic qualifications gained - ", "", attr(merged[[v]], "label"))
  if (is.null(sub)) { attr(merged[[v]], "label") }
})

# create factor levels
max_code <- max(educadtl32_code, na.rm = TRUE)
# but we need to know number of substantive vars: count of acad_vars
n_sub <- length(acad_vars)
last_code <- n_sub + 1
levels_vec <- c(acad_labels, "None of these qualifications")

educadtl32_factor <- factor(educadtl32_code, levels = c(1:last_code, -8, -9, -2, -1, -3), labels = c(levels_vec, "Don't know", "Refused", "No answer", "Not applicable", "Not asked at fieldwork stage"), ordered = TRUE)

# ---------------------------------
# Educvdtl32 - detailed vocational qualifications
# ---------------------------------
voc_vars <- paste0("W9VCQU0", LETTERS[0:15])
# compute code similarly
compute_voc_code <- function(row) {
  code <- NULL
  last_substantive <- 0
  for (i in seq_along(voc_vars)) {
    val <- row[[voc_vars[i]]]
    if (is.na(val)) next
    if (val == -3) next # Not asked
    if (val == -1) next # Not applicable (not present)
    if (val == -8) { code <- -8; return(code) }
    if (val == -9) { code <- -9; return(code) }
    if (val == -2) { code <- -2; return(code) }
    if (val == 1 || val == 2) {
      last_substantive <- last_substantive + 1
      if (val == 1) { code <- last_substantive; return(code) }
    }
  }
  if (last_substantive == 0) {
    return(-3)
  } else {
    return(last_substantive + 1)
  }
}

educvdtl32_code <- apply(merged, 1, compute_voc_code)
# labels
voc_labels <- sapply(voc_vars, function(v) {
  sub <- sub("Vocational qualifications gained - ", "", attr(merged[[v]], "label"))
  if (is.null(sub)) attr(merged[[v]], "label")
})
last_voc_code <- length(voc_vars) + 1
levels_vec_voc <- c(voc_labels, "None of these qualifications")
educvdtl32_factor <- factor(educvdtl32_code, levels = c(1:last_voc_code, -8, -9, -2, -1, -3), labels = c(levels_vec_voc, "Don't know", "Refused", "No answer", "Not applicable", "Not asked at fieldwork stage"), ordered = TRUE)

# ---------------------------------
# Prepare final output
# ---------------------------------
final_df <- merged %>% select(NSID) %>%
  mutate(educ25 = educ25_factor,
         educ32 = educ32_factor,
         educadtl32 = educadtl32_factor,
         educvdtl32 = educvdtl32_factor)

# Write csv
output_dir <- "data/output"
if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE)
write_csv(final_df, file.path(output_dir, "cleaned_data.csv"))

# Done

