# Standard missing value mapping function
standardize_missing <- function(x) {
  # R NA -> -3 unless already negative meaning exists
  rec <- case_when(
    is.na(x) ~ -3L,
    x == -9 ~ -9L,
    x == -8 ~ -8L,
    x == -7 ~ -7L,
    x == -6 ~ -6L,
    x == -5 ~ -5L,
    x == -4 ~ -4L,
    x == -3 ~ -3L,
    x == -2 ~ -2L,
    x == -1 ~ -1L,
    TRUE ~ as.integer(x)
  )
