}

# ---------------------------------
# Educ25 - collapsed NVQ scheme at age 25
# ---------------------------------
# Mapping for vocational tick boxes to NVQ tier
# 0 = NVQ 4–5, 1 = NVQ 1–3, 2 = Entry level or none, 3 = Other, 4 = None

# define mapping for each W8VCQU variable (we use vector of variable names in order)
vc_vars <- c(
  "W8VCQU0A", "W8VCQU0B", "W8VCQU0C", "W8VCQU0D", "W8VCQU0E",
  "W8VCQU0F", "W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J",
  "W8VCQU0K", "W8VCQU0L", "W8VCQU0M", "W8VCQU0N", "W8VCQU0O",
  "W8VCQU0P", "W8VCQU0Q", "W8VCQU0R"
)

# mapping function: returns NVQ tier or NA
map_vc_to_tier <- function(val) {
  # val: 1 Yes => tier, 0 No => NA
  if (is.na(val)) return(NA)
  if (val == -9) return(-9)
  if (val == -8) return(-8)
  if (val == -1) return(-1)
  if (val == 1) {
    # determine tier based on variable context (captured by outer variable name)
    # use mapping defined below
    return(NA) # placeholder, will handle outside
  }
  if (val == 0) return(NA)
