}

# We'll handle mapping via a named vector of tiers for Yes values
# tier mapping: 0=NVQ 4-5, 1=NVQ 1-3, 2=Entry/no, 3=Other, 4=None
# we approximate mapping based on variable name
vc_tier_map <- c(
  W8VCQU0A = 1, # Youth training certificate - NVQ1-3
  W8VCQU0B = 1, # Key Skills - NVQ1-3
  W8VCQU0C = 1, # Basic skills - NVQ1-3
  W8VCQU0D = 2, # Entry level - Entry
  W8VCQU0E = 0, # Modern apprenticeship - NVQ4-5
  W8VCQU0F = 0, # RSA/OCR - NVQ4-5
  W8VCQU0G = 0, # City & Guilds - NVQ4-5
